const fs = require('node:fs');
const path = require('node:path');

const { buildTypesModule, BUNDLE } = require('./emit-types-module.js');
const { appendMappings } = require('./declaration-map.js');

/*
public/types/index.d.ts is emitted by tsc as a single bundled declaration file
whose modules are named after their source paths, so the public barrel comes out
as `declare module "QCObjects"`. The package is published as `qcobjects`, so a
consumer writing

    import { CONFIG, Component, RegisterWidgets } from "qcobjects";

resolves to no declaration at all.

This script finishes the published type surface:

1. appends the package-named alias, `declare module "qcobjects"`, re-exporting
   the barrel — and, when a types module was injected, the public types too, so
   `IComponent` and friends are importable under the package name rather than
   only resolvable inside signatures.
2. injects `declare module "types"` carrying the public type closure.

Step 2 exists because the bundle references the bare specifier "types", which
resolves only through the repo-internal `paths` mapping in tsconfig.d.json and
is never published. A consumer therefore reports TS2307 once per import site.
The specifier is a fossil of the external `@types/qcobjects` package
(github:QCObjects/-types-qcobjects), removed in de295144. Emitting the needed
declarations as one ambient module makes them resolve, and because the file is a
global script that module is visible to every other block in it — so no import
site is rewritten.

Everything here is a pure function of the emitted bundle, which is what lets the
same logic run unchanged from this postbuild hook today and from inside
transpile.js once Core stops shelling out to tsc.
*/

const ALIAS = 'declare module "qcobjects"';
const TYPES_MODULE = 'declare module "types"';
const SOURCE_MAP_URL = '//# sourceMappingURL=index.d.ts.map';

function readBundle() {
  try {
    return fs.readFileSync(BUNDLE, 'utf8');
  } catch (err) {
    console.error('Failed to read', BUNDLE, err);
    process.exit(1);
  }
}

/*
Generated sections are fenced with sentinel comments so a previous run's output
can be removed wholesale. tsconfig.d.json is composite, so a rebuild with no
source changes skips emit and leaves the last run's output in place; appending
unconditionally would stack a duplicate module per build.
*/
const FENCE_START = '// >>> generated by postbuild.js — do not edit >>>';
const FENCE_END = '// <<< generated by postbuild.js <<<';

/** Remove every generated section plus tsc's trailing module marker. */
function stripGenerated(text) {
  const fenced = new RegExp(
    `${escapeForRegExp(FENCE_START)}[\\s\\S]*?${escapeForRegExp(FENCE_END)}\\n?`,
    'g',
  );

  return text
    .replace(fenced, '')
    .replace(/^export \{\};?\s*$/m, '')
    .replace(new RegExp(`\\n*${escapeForRegExp(SOURCE_MAP_URL)}`), '')
    .replace(/\s+$/, '\n');
}

function escapeForRegExp(text) {
  return text.replace(/[.*+?^${}()|[\]\\/]/g, '\\$&');
}

/** Highest generated line index tsc already mapped, in its own output. */
function lastMappedLine(text) {
  const trimmed = text.replace(/\s+$/, '');
  return trimmed.split('\n').length - 1;
}

function main() {
  const types = buildTypesModule();
  const base = stripGenerated(readBundle()).replace(/\n$/, '');

  const generated = [];

  if (types.code) {
    generated.push(
      [
        '/*',
        ' * Generated by emit-types-module.js — do not edit.',
        ` * Public type closure: ${types.names.length} of ${types.declared}`,
        ' * declarations in src/types/global/index.d.ts, reachable from the',
        ` * exported surface. The remaining ${types.internalOnly.length} are`,
        ' * internal and deliberately absent.',
        ' */',
        `${TYPES_MODULE} {`,
        types.code,
        '}',
      ].join('\n'),
    );
  }

  const aliasLines = [`${ALIAS} {`, '    export * from "QCObjects";'];
  if (types.code) aliasLines.push('    export * from "types";');
  aliasLines.push('}');
  generated.push(aliasLines.join('\n'));

  const section = [
    FENCE_START,
    generated.join('\n\n'),
    FENCE_END,
    SOURCE_MAP_URL,
  ].join('\n');

  /*
  tsc's own sourceMappingURL is stripped from the base, so the finished file
  carries exactly one — and it sits last, where tooling expects it.
  */
  const output = `${base}\n\n${section}\n`;
  fs.writeFileSync(BUNDLE, output, 'utf8');

  if (types.code) {
    updateSourceMap(types, base);
    console.log(
      `Injected declare module "types" with ${types.names.length} declarations ` +
        `(${types.internalOnly.length} internal-only withheld)`,
    );
  }
  console.log('Wrote declare module "qcobjects" into index.d.ts');
}

/**
 * Point index.d.ts.map at the injected declarations so they navigate like the
 * rest of the bundle. Without this the 46 public types would be the only
 * declarations in the file with no go-to-definition.
 */
function updateSourceMap(types, base) {
  const mapPath = path.join(path.dirname(BUNDLE), 'index.d.ts.map');

  let mapJson;
  try {
    mapJson = JSON.parse(fs.readFileSync(mapPath, 'utf8'));
  } catch (err) {
    console.warn('Could not read index.d.ts.map, leaving it untouched:', err.message);
    return;
  }

  /*
  Where the injected block actually begins in the finished bundle. That block
  carries a leading comment and the `declare module "types"` line, so it starts
  after the fence, not at the end of the base — reading it back off the emitted
  text is more reliable than predicting the layout.
  */
  const emitted = fs.readFileSync(BUNDLE, 'utf8');
  const blockLine = emitted
    .split('\n')
    .findIndex((line) => line.trim() === `${TYPES_MODULE} {`);

  if (blockLine === -1) {
    console.warn('Injected types module not found in bundle, leaving map untouched.');
    return;
  }

  /*
  Positions were recorded relative to the start of the emitted type block, so
  the first declaration sits one line past `declare module "types" {`.
  */
  const blockStart = blockLine + 1;
  const mappedThrough = lastMappedLine(base);

  const entries = types.positions.map((position) => ({
    genLine: blockStart + position.genLine,
    genCol: position.genCol,
    srcLine: position.srcLine,
    srcCol: position.srcCol,
  }));

  appendMappings(mapJson, '../../src/types/global/index.d.ts', entries, mappedThrough);

  fs.writeFileSync(mapPath, JSON.stringify(mapJson), 'utf8');
  console.log(`Added ${entries.length} declaration mappings to index.d.ts.map`);
}

main();
